func localeFor(code string) localeDefinition {
	if l, ok := locales[code]; ok {
		return l
	}
	return locales["en"]
}

func tr(code, key string) string {
	l := localeFor(code)
	if s, ok := l.Text[key]; ok {
		return s
	}
	if s, ok := locales["en"].Text[key]; ok {
		return s
	}
	return key
}

func trf(code, key string, args ...interface{}) string {
	return fmt.Sprintf(tr(code, key), args...)
}
